.folder-workspace .notes-metric:nth-child(3){background:radial-gradient(ellipse at top right,#34aa9e,transparent 80%),#07564f}
.folder-workspace .notes-metric strong{font-size:42px;margin-top:38px;line-height:1.1;position:relative;z-index:1}
.folder-workspace .notes-metric>svg{position:absolute;right:18px;top:30px;width:86px;height:86px;pointer-events:none}
.folder-workspace .notes-metric>i{display:none}
.folder-workspace .notes-metric small{position:relative;z-index:1;max-width:85%}
.folder-workspace .folder-card-grid>a:hover{background:var(--bg-input,#f5f7ff)}
