</style>
<style>
.folder-colored-header .page-hero{background:linear-gradient(110deg,color-mix(in srgb,var(--folder-color) 8%,transparent),transparent 65%),var(--bg-card,#fff);border-color:color-mix(in srgb,var(--folder-color) 23%,var(--border-glass))}
.folder-colored-header .hero-emblem{color:var(--folder-color)!important;background:color-mix(in srgb,var(--folder-color) 12%,var(--bg-card,#fff))!important}
.folder-quick-actions{display:flex;align-items:center;gap:10px;margin:-8px 0 20px;flex-wrap:wrap}.folder-menu{position:relative}.folder-menu summary{list-style:none;cursor:pointer}.folder-menu-items{position:absolute;top:calc(100% + 6px);left:0;min-width:210px;background:var(--bg-card,#fff);border:1px solid var(--border-glass);border-radius:14px;box-shadow:0 12px 30px #14204420;padding:8px;z-index:40}.folder-menu-items a{display:flex;align-items:center;gap:8px;padding:10px;border-radius:8px;font-size:13px}.folder-menu-items a:hover{background:var(--bg-input,#f5f7ff)}
.folder-simple-nav{display:flex!important;flex-wrap:nowrap!important;overflow:visible;gap:5px}.folder-simple-nav a{flex:1;justify-content:center;white-space:nowrap;padding:12px 8px!important;font-size:13px!important}.folder-work-picker{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:20px}.folder-work-picker select{min-width:150px}
.visual-folder-map{background:radial-gradient(ellipse at center,color-mix(in srgb,var(--folder-color) 6%,transparent),transparent 60%),var(--bg-card,#fff)}
.visual-hub{grid-template-columns:repeat(4,minmax(0,1fr));grid-template-rows:145px 130px 145px;gap:14px;padding:18px 0}.visual-hub .folder-map-lines{color:color-mix(in srgb,var(--folder-color) 35%,transparent)}
.visual-hub .folder-map-center{color:var(--text-primary);background:color-mix(in srgb,var(--folder-color) 9%,var(--bg-card,#fff));border-color:color-mix(in srgb,var(--folder-color) 40%,transparent);box-shadow:0 0 32px color-mix(in srgb,var(--folder-color) 10%,transparent)}.visual-hub .folder-map-center i{color:var(--folder-color);font-size:36px}
.visual-map-node{width:100%;max-width:none;text-align:left;gap:8px;position:relative;overflow:hidden;color:var(--text-primary);cursor:pointer;padding:14px;align-self:center;min-height:115px}.visual-map-node:hover,.visual-map-node:focus-visible{border-color:var(--folder-color);box-shadow:0 8px 24px color-mix(in srgb,var(--folder-color) 15%,transparent)}.visual-map-node.is-empty{min-height:95px}.map-node-art{width:48px;flex:none;filter:drop-shadow(0 4px 4px #1b29451c)}.map-node-art svg{width:100%;height:55px}.map-node-copy{min-width:0;flex:1}.map-node-copy strong{font-size:12px}.map-node-copy small{display:block;margin:3px 0}.map-node-add{font-size:11px;color:var(--folder-color)}.map-node-preview{display:block;font-size:10px;line-height:1.4;color:var(--text-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.map-brand-swatches{display:flex;gap:4px;margin-top:6px}.map-brand-swatches i{width:14px;height:14px;border-radius:50%;border:1px solid #8c95a333}.map-node-thumb{height:22px;width:22px;border-radius:6px;object-fit:cover;display:inline-block;margin-top:5px}
.map-panel-backdrop{position:fixed;inset:0;background:#10182e50;z-index:120;display:flex;justify-content:flex-end}.map-detail-panel{width:min(460px,100%);height:100%;overflow:auto;border-radius:22px 0 0 22px!important;background:var(--bg-card,#fff);margin:0!important;box-shadow:-12px 0 40px #10182e30}.map-detail-panel:focus{outline:none}.map-detail-panel .folder-resource-row{padding:16px 0}
