@media(max-width:640px){.folder-simple-nav a{font-size:11px!important;padding:10px 4px!important}.visual-hub{display:flex;flex-direction:column;gap:10px}.visual-hub .folder-map-center{order:-1;width:100%;display:flex;align-items:center;gap:10px}.visual-hub .folder-map-node{width:100%;min-height:80px;padding:14px;border-left:3px solid color-mix(in srgb,var(--folder-color) 35%,transparent)}.map-node-art{width:45px}.map-node-copy strong{font-size:13px}.visual-map-node.is-empty{min-height:66px}.map-node-add{float:right}.visual-hub .folder-map-lines{display:none}}
