<style>.folder-quick-actions>.folder-menu:first-child>summary{background:#365ce9;color:#fff;border-color:#365ce9}.visual-hub .folder-map-center small{display:block}.visual-map-node[aria-expanded=true]{border-color:var(--folder-color)}</style>
<style>
.map-panel-backdrop{z-index:2147483647;align-items:center;justify-content:center;padding:24px;background:#10182e66;backdrop-filter:blur(3px)}
.map-detail-panel.notes-card{width:min(620px,100%);height:auto;max-height:calc(100dvh - 48px);padding:0!important;overflow:hidden;border-radius:24px!important;box-shadow:0 24px 80px #10182e40}
