.map-panel-header{display:flex;gap:14px;align-items:center;padding:24px;border-bottom:1px solid var(--border-glass,#dbe1ec);flex-shrink:0;background:linear-gradient(110deg,color-mix(in srgb,var(--folder-color) 7%,transparent),transparent)}
.map-panel-emblem{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;flex:none;background:color-mix(in srgb,var(--folder-color) 12%,transparent);color:var(--folder-color);font-size:19px}
.map-panel-heading{min-width:0;flex:1}.map-panel-heading h2{margin:0;font-size:18px!important;line-height:1.35;overflow-wrap:anywhere}.map-panel-heading p{font-size:12px;color:var(--text-muted);margin:4px 0 0;overflow-wrap:anywhere}
.map-panel-close{display:grid;place-items:center;width:36px;height:36px;flex:none;border:1px solid var(--border-glass,#dbe1ec);border-radius:11px;color:var(--text-secondary);background:var(--bg-card,#fff)}
.map-panel-body{padding:20px 24px;display:flex;flex-direction:column;gap:12px;overflow-y:auto;overscroll-behavior:contain;min-height:0}
.map-item-card{display:flex;gap:12px;align-items:center;padding:16px;border:1px solid var(--border-glass,#dbe1ec);border-radius:15px;background:var(--bg-card,#fff);color:var(--text-primary);min-height:78px;flex-shrink:0}
.map-item-card:hover{border-color:var(--folder-color);background:color-mix(in srgb,var(--folder-color) 4%,var(--bg-card,#fff))}.map-item-icon{width:36px;height:36px;flex:none;border-radius:10px;background:color-mix(in srgb,var(--folder-color) 9%,transparent);color:var(--folder-color);display:grid;place-items:center}.map-item-copy{min-width:0;flex:1}.map-item-copy strong{display:block;font-size:14px;line-height:1.4;overflow-wrap:anywhere}.map-item-copy small{display:block;font-size:11px;color:var(--text-muted);margin-top:4px}.map-item-open{font-size:12px;display:flex;align-items:center;gap:7px;flex:none;color:var(--text-secondary)}
.map-panel-footer{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:18px 24px;border-top:1px solid var(--border-glass,#dbe1ec);flex-shrink:0;background:var(--bg-card,#fff)}.map-panel-footer .form-chip{font-size:12px;padding:10px 12px}.map-panel-footer .map-panel-primary{background:#365ce9;color:#fff;border-color:#365ce9;margin-left:auto}.map-panel-empty{display:grid;justify-items:center;text-align:center;gap:12px;padding:30px 12px}.map-panel-empty>i{font-size:28px;color:var(--folder-color)}.map-panel-empty strong{font-size:15px}.map-panel-empty p{font-size:12px;line-height:1.6;color:var(--text-muted);max-width:34ch}
.map-item-card:focus-visible,.map-panel-close:focus-visible{outline:2px solid var(--folder-color);outline-offset:3px}
@media(max-width:640px){.map-panel-backdrop{padding:12px}.map-detail-panel.notes-card,.map-panel-section{max-height:calc(100dvh - 24px)}.map-panel-header{padding:18px;gap:10px}.map-panel-body{padding:16px;gap:10px}.map-panel-footer{padding:14px 16px}.map-item-card{padding:13px;gap:10px}.map-item-open{font-size:0;gap:0}.map-item-open i{font-size:12px}.map-panel-footer .map-panel-primary{margin-left:0}}
</style>
<style>
.folder-reports-premium{color:var(--text-primary)}.folder-reports-premium>.folder-panel-head{margin:24px 0 18px}.folder-health-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:22px}
.folder-health-stat{--ov-tone:#153d80;position:relative;overflow:hidden;min-height:210px;border-radius:24px;padding:23px;background:radial-gradient(ellipse at top right,#5999f3,transparent 80%),#153d80;color:white;box-shadow:inset 0 1px 1px #ffffff66,0 12px 25px #153d8018;display:flex;flex-direction:column;align-items:flex-start}
.folder-health-stat:nth-child(2){--ov-tone:#512b80;background:radial-gradient(ellipse at top right,#a075ef,transparent 80%),#512b80}.folder-health-stat:nth-child(3){--ov-tone:#07564f;background:radial-gradient(ellipse at top right,#34aa9e,transparent 80%),#07564f}.folder-health-stat:nth-child(4){--ov-tone:#7d4215;background:radial-gradient(ellipse at top right,#efa928,transparent 80%),#7d4215}
.folder-health-stat>span{font-size:14px;font-weight:600;position:relative;z-index:1}.folder-health-stat>svg{position:absolute;right:10px;top:44px;width:78px;height:78px;pointer-events:none}.folder-health-stat>strong{font-size:42px;line-height:1.1;letter-spacing:-1px;margin-top:62px;position:relative;z-index:1}.folder-health-stat>small{font-size:11px;line-height:1.5;opacity:.82;margin-top:10px;position:relative;z-index:1}
.folder-health-details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:20px}.folder-health-detail h3,.folder-health-insights h3{font-size:15px;font-weight:700;margin:0 0 16px}.folder-health-detail h3{display:flex;align-items:center;gap:10px}.folder-health-detail h3 i{color:#5472ed}.folder-health-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:13px 0;border-top:1px solid var(--border-glass,#e2e8f0)}.folder-health-row>span{min-width:0}.folder-health-row strong{font-size:12px;font-weight:600;display:block}.folder-health-row small{font-size:10px;line-height:1.5;color:var(--text-muted);display:block;margin-top:4px}.folder-health-row b{font-size:19px;flex:none;font-weight:650}.folder-health-insights{display:grid;grid-template-columns:1fr 1fr;gap:18px}.folder-health-insights .notes-hint{margin-bottom:14px}.folder-report-empty{padding:22px 0;color:var(--text-muted);font-size:12px;line-height:1.7;display:grid;gap:10px}.folder-report-empty i{color:#5472ed;font-size:22px}.folder-report-disclosure{padding:16px 2px 0}.folder-health-insights .folder-report-bar{grid-template-columns:minmax(110px,1fr) minmax(50px,1fr) 30px}
