@media(max-width:640px){.folder-health-stats{gap:10px}.folder-health-stat{padding:16px;border-radius:18px;min-height:190px}.folder-health-stat>strong{font-size:32px;margin-top:58px}.folder-health-stat>span{font-size:12px}.folder-health-stat>svg{width:58px;height:58px;top:43px}.folder-health-stat>small{font-size:10px}.folder-health-insights{grid-template-columns:1fr}}
